interface Component { fun update(dt: Float) }

class Entity(private val physics: Physics) : Physics by physics {
    private val parts = mutableListOf<Component>()
    fun add(component: Component) = apply { parts.add(component) }
    fun update(dt: Float) = parts.forEach { it.update(dt) }
}

data class Transform(var x: Float = 0f, var y: Float = 0f)
